# Block 3b: Read Cancellation Messages
import re as re_module

def read_messages_data():
    """Read messages blobs and extract cancellation reason/note per event_id.
    Multiple files per event_id possible (reason edits) — latest timestamp wins."""

    empty_schema = StructType([
        StructField("event_id", LongType(), True),
        StructField("cancellation_reason", StringType(), True),
        StructField("cancellation_note", StringType(), True)
    ])

    try:
        if not mssparkutils.fs.exists(MESSAGES_DIRECTORY):
            print("ℹ️ No messages directory found")
            return spark.createDataFrame([], empty_schema)

        files = mssparkutils.fs.ls(MESSAGES_DIRECTORY)
        json_files = [f for f in files if f.name.lower().endswith('.json')]

        if not json_files:
            print("ℹ️ No messages files found")
            return spark.createDataFrame([], empty_schema)

        print(f"🔍 Found {len(json_files)} messages files")

        # event_id -> {timestamp, reason, note} — latest timestamp wins
        results = {}

        for file in json_files:
            try:
                # Filename: messages_{event_id}_{timestamp}.json
                name = file.name.replace('.json', '')
                parts = name.split('_')
                event_id = int(parts[1])
                file_timestamp = '_'.join(parts[2:])

                # Read file via Spark (consistent with Block 3 approach)
                raw_df = spark.read.option("multiLine", "true").json(file.path)
                rows = raw_df.collect()

                if not rows:
                    continue

                row_dict = rows[0].asDict(recursive=True)
                messages = row_dict.get('data', [])

                if not isinstance(messages, list):
                    continue

                # Last note with "Geannuleerd:" wins within this file
                reason = None
                note = None
                for msg in messages:
                    if not isinstance(msg, dict):
                        continue
                    if msg.get('type') != 'note':
                        continue
                    html = msg.get('message', '')
                    strong_match = re_module.search(r'<strong>Geannuleerd:\s*([^<]+)<\/strong>', html)
                    if not strong_match:
                        continue
                    reason = strong_match.group(1).strip()
                    note_match = re_module.search(r'<\/strong><\/p><p>([^<]+)<\/p>', html)
                    note = note_match.group(1).strip() if note_match else None

                if reason:
                    if event_id not in results or file_timestamp > results[event_id]['timestamp']:
                        results[event_id] = {
                            'timestamp': file_timestamp,
                            'reason': reason,
                            'note': note
                        }

            except Exception as e:
                print(f"⚠️ Error processing {file.name}: {e}")
                continue

        if not results:
            print("ℹ️ No cancellation reasons found")
            return spark.createDataFrame([], empty_schema)

        records = [
            {
                "event_id": int(eid),
                "cancellation_reason": v['reason'],
                "cancellation_note": v['note']
            }
            for eid, v in results.items()
        ]

        messages_df = spark.createDataFrame(records, schema=empty_schema)
        print(f"✅ Cancellation reasons: {messages_df.count()}")
        return messages_df

    except Exception as e:
        print(f"⚠️ Error reading messages data: {e}")
        traceback.print_exc()
        return spark.createDataFrame([], empty_schema)

print("✓ Block 3b completed: Messages reader")
